EVALUATE CALCULATETABLE(
    SUMMARIZECOLUMNS('Time Calc'[Time Calculation], "v", [Total Sales]),
    NOT ('Orders'[Status] IN {"Cancelled"}),
    'Date'[Year Month] IN {"2025-06"}
)

